CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS businesses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,phone text DEFAULT '',email text DEFAULT '',address text DEFAULT '',default_rate numeric(10,2) DEFAULT 10,penalty_rate numeric(10,2) DEFAULT 2,grace_days int DEFAULT 3,risk_ratio numeric(10,2) DEFAULT 50,alert_days int DEFAULT 3,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,name text NOT NULL,username text UNIQUE NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN('Admin','Manager','Loan Officer','Cashier')),active boolean DEFAULT true,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,customer_code text,name text NOT NULL,phone text,email text,reference text,dob date,occupation text,employer text,monthly_income numeric(14,2) DEFAULT 0,address text,notes text,created_at timestamptz DEFAULT now(),UNIQUE(business_id,customer_code));
CREATE TABLE IF NOT EXISTS applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,application_code text,customer_id uuid REFERENCES customers(id),application_date date DEFAULT CURRENT_DATE,amount numeric(14,2) NOT NULL,term_months int,rate_monthly numeric(10,2),monthly_income numeric(14,2),monthly_expenses numeric(14,2),disposable_income numeric(14,2),estimated_installment numeric(14,2),debt_income_ratio numeric(10,2),risk text,guarantor_name text,guarantor_phone text,security text,purpose text,notes text,status text DEFAULT 'Pending',reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz DEFAULT now(),UNIQUE(business_id,application_code));
CREATE TABLE IF NOT EXISTS loans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,loan_code text,application_id uuid REFERENCES applications(id),customer_id uuid NOT NULL REFERENCES customers(id),principal numeric(14,2) NOT NULL,rate_monthly numeric(10,2),term_months int,interest numeric(14,2),total_payable numeric(14,2),borrow_date date,due_date date,frequency text,purpose text,security text,status text DEFAULT 'Active',created_at timestamptz DEFAULT now(),UNIQUE(business_id,loan_code));
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,receipt_code text,loan_id uuid NOT NULL REFERENCES loans(id),customer_id uuid NOT NULL REFERENCES customers(id),payment_date date DEFAULT CURRENT_DATE,amount numeric(14,2) NOT NULL,method text,reference text,created_at timestamptz DEFAULT now(),UNIQUE(business_id,receipt_code));
CREATE TABLE IF NOT EXISTS expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,expense_code text,expense_date date DEFAULT CURRENT_DATE,category text,amount numeric(14,2) NOT NULL,payee text,reference text,description text,created_at timestamptz DEFAULT now(),UNIQUE(business_id,expense_code));
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,customer_id uuid REFERENCES customers(id),document_type text,file_name text,storage_key text,uploaded_by uuid REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY,business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id),action text NOT NULL,details jsonb DEFAULT '{}'::jsonb,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_customers_business ON customers(business_id);CREATE INDEX IF NOT EXISTS idx_loans_business ON loans(business_id);CREATE INDEX IF NOT EXISTS idx_payments_business ON payments(business_id);
